      "operands": ["entry->obj", "obj"],
      "relation": {"op": "ne", "left": "entry->obj", "right": "obj"}
    },
    "sink": {
      "file": "source/pdf/pdf-xref.c",
      "function": "pdf_resolve_indirect_chain",
      "line": 2580,
      "operands": ["ref"],
      "relation": {"op": "ne", "left": "ref", "right": "NULL"}
    },
    "propagation": [
      {
        "from": {"file": "source/pdf/pdf-xref.c", "function": "pdf_read_new_xref_section", "line": 1337, "operands": ["entry->type", "t"]},
        "to": {"file": "source/pdf/pdf-xref.c", "function": "pdf_cache_object", "line": 2500, "operands": ["orig_x->type"]},
        "type": "control",
        "via": ["entry->type"],
        "relation": {"op": "eq", "left": "entry->type", "right": "'o'"}
      },
      {
        "from": {"file": "source/pdf/pdf-xref.c", "function": "pdf_load_obj_stm", "line": 2108, "operands": ["obj"]},
        "to": {"file": "source/pdf/pdf-xref.c", "function": "pdf_load_obj_stm", "line": 2134, "operands": ["entry->obj", "obj"]},
        "type": "data",
        "via": ["obj"],
        "relation": {"op": "same_object", "left": "entry->obj", "right": "obj"}
      },
      {
        "from": {"file": "source/pdf/pdf-xref.c", "function": "pdf_load_obj_stm", "line": 2134, "operands": ["entry->obj", "obj"]},
        "to": {"file": "source/pdf/pdf-xref.c", "function": "pdf_resolve_indirect", "line": 2570, "operands": ["entry->obj"]},
        "type": "data",
        "via": ["entry->obj"],
        "relation": {"op": "same_object", "left": "entry->obj", "right": "obj"}
      },
      {
        "from": {"file": "source/pdf/pdf-xref.c", "function": "pdf_resolve_indirect", "line": 2570, "operands": ["entry->obj"]},
        "to": {"file": "source/pdf/pdf-xref.c", "function": "pdf_resolve_indirect_chain", "line": 2580, "operands": ["ref"]},
